    'Incident ray',
    'The incoming ray travels inside n₁ and meets the boundary at angle θ₁ from the normal. Everything that happens next is decided by comparing sin θ₁ with n₂/n₁.', 14 * s);

  /* --- reflected ray --- */
  var rw = (2.0 + 2.2 * R) * s;
  var rx = cx + ur.x * Lb, ry = cy + ur.y * Lb;
  g.line(cx, cy, rx, ry).stroke({ color: TEAL, width: rw, linecap: 'round' });
  arrowHead(g, cx + ur.x * Lb * 0.62, cy + ur.y * Lb * 0.62, ur.x, ur.y, aw * (0.95 + 0.25 * R), TEAL);
  hitLine(g, cx, cy, rx, ry,
    'Reflected ray — θ₁ = ' + o.theta1.toFixed(0) + '°, carrying ' + Math.round(R * 100) + '% of the light',
    'Reflected ray',
    'Reflection always obeys angle in = angle out. Its share of the energy grows as θ₁ approaches θc, and reaches 100% beyond it — which is why the line thickens here.', 14 * s);

  /* angle arcs below the surface */
  var midL = arcBetween(g, cx, cy, 46 * s, { x: 0, y: 1 }, ui, TEAL_D, 1.2 * s);
  var midR = arcBetween(g, cx, cy, 46 * s, { x: 0, y: 1 }, ur, TEAL_D, 1.2 * s);
  function angLabel(sub, mid) {
    var lx = cx + 68 * s * Math.cos(mid), ly = cy + 68 * s * Math.sin(mid);
    if (sub === 'c') thetaC(g, lx, ly, 21 * s, INK);
    else txt(g, 'θ₁', lx, ly, { size: 21 * s, italic: true, family: 'Georgia, serif', anchor: 'middle', baseline: 'middle', fill: INK });
  }
  angLabel(o.subLeft || '1', midL);
  angLabel(o.subRight || '1', midR);

  /* medium labels */
  txt(g, 'n₂', o.left + 60 * s, cy - (o.normUp * 0.62), { size: 24 * s, italic: true, family: 'Georgia, serif', anchor: 'middle', baseline: 'middle' });
  txt(g, 'n₁', o.right - 55 * s, cy + 40 * s, { size: 24 * s, italic: true, family: 'Georgia, serif', anchor: 'middle', baseline: 'middle' });

  /* total internal reflection annotation */
  if (!hasRefr) {
    var tx = cx + (o.right - cx) * (o.showNames ? 0.58 : 0.62);
    var ty = cy + (o.bottom - cy) * (o.showNames ? 0.62 : 0.75);
    var tt = txt(g, 'Total internal\nreflection', tx, ty,
      { size: 17 * s, anchor: 'middle', baseline: 'middle', fill: INK, haloW: 4 });
    inter(tt, 'No refracted ray exists — all light stays in n₁',
      'Total internal reflection',
      'For θ₁ > θc, sin θ₂ = sin θ₁ /(n₂/n₁) would exceed 1. No real angle has a sine bigger than 1, so Snell\'s law has no solution: the refracted ray simply does not exist and 100% of the light reflects.');
  }

  /* ray name labels (full panel only) */
  if (o.showNames) {
    txt(g, 'Incident ray', o.left + 22, o.bottom - 34, { size: 15, baseline: 'middle' });
    leader(g, o.left + 118, o.bottom - 40, cx + ui.x * Lb * 0.78, cy + ui.y * Lb * 0.78);
    var side1 = (th1 < 30 * RAD) ? 1 : -1;
    var lx2 = cx + ur.x * Lb * 0.74 + side1 * Math.cos(th1) * 38;
    var ly2 = cy + ur.y * Lb * 0.74 - side1 * Math.sin(th1) * 38;
    txt(g, 'Reflected ray', lx2, ly2, { size: 15, anchor: 'middle', baseline: 'middle' });
  }

  return { thc: thc, th2: th2, hasRefr: hasRefr, R: R, T: T, sin2: sin2 };
}

/* ---------- readout panel ---------- */
function drawReadout(g, d) {
  var x = 648, y = 16, w = 296, h = 156;
  g.rect(w, h).move(x, y).radius(7).fill('#ffffff').stroke({ color: '#cfd8de', width: 1 }).opacity(0.96);
  var px = x + 14, py = y + 12, lh = 20;
  txt(g, 'θ₁ = ' + state.theta1.toFixed(0) + '°', px, py, { size: 14, fill: TEAL_D, weight: '700', halo: false });
  py += lh;
  if (d.hasRefr) {
    txt(g, 'θ₂ = ' + (d.th2 / RAD).toFixed(1) + '°' + (d.th2 >= 86 * RAD ? '  (grazing)' : ''), px, py,
      { size: 14, fill: TEAL_D, weight: '700', halo: false });
  } else {
    txt(g, 'θ₂ = none — no refracted ray', px, py, { size: 14, fill: '#c0392b', weight: '700', halo: false });
  }
  py += lh;
  txt(g, 'n₂ / n₁ = ' + state.ratio.toFixed(2) + '     θc = ' + (d.thc / RAD).toFixed(1) + '°', px, py,
    { size: 14, fill: '#333', halo: false });
  py += lh - 4;
  g.line(px, py + 8, x + w - 14, py + 8).stroke({ color: '#e2e7ea', width: 1 });
  py += 14;
  txt(g, 'n₁ sin θ₁ = n₂ sin θ₂', px, py, { size: 14, italic: true, family: 'Georgia, serif', fill: '#222', halo: false });
  py += lh;
  var val = d.sin2;
  txt(g, 'sin θ₂ = sin θ₁ ÷ (n₂/n₁) = ' + val.toFixed(3) + (d.hasRefr ? '' : '  > 1  ✗'), px, py,
    { size: 13.5, italic: true, family: 'Georgia, serif', fill: d.hasRefr ? '#222' : '#c0392b', halo: false });
  py += lh;
  txt(g, 'sin θc = n₂ / n₁ = ' + state.ratio.toFixed(2), px, py,
    { size: 13.5, italic: true, family: 'Georgia, serif', fill: '#222', halo: false });

  var hot = g.rect(w, h).move(x, y).fill('#fff').opacity(0);
  inter(hot, 'Live values and the two governing equations',
    'Reading the numbers',
    'Snell\'s law is solved for sin θ₂. While that value stays below 1 a refracted ray exists; the instant it passes 1, no angle can satisfy the equation and the refraction term disappears from the physics.');
}

/* ---------- render ---------- */
function render() {
  root.clear();
  if (!state.triptych) {
    var d = drawScene(root, {
      theta1: state.theta1, ratio: state.ratio,
      cx: 400, cy: 300, left: 40, right: 920, bottom: 482, topY: 40,
      normUp: 232, normDown: 168, Lmax: 216, scale: 1,
      showNames: true, showThetaC: true
    });
    drawReadout(root, d);
  } else {
    var thc = Math.asin(Math.min(1, state.ratio)) / RAD;
    var a = Math.max(6, thc * 0.6);
    var b = thc;
    var c = (state.theta1 > thc + 2) ? Math.min(87, state.theta1) : Math.min(87, thc + 18);
    var panels = [
      { cx: 168, th: a, cap: '(a)', sl: '1', sr: '1', tc: false },
      { cx: 480, th: b, cap: '(b)', sl: 'c', sr: 'c', tc: false },
      { cx: 792, th: c, cap: '(c)', sl: '1', sr: '1', tc: true }
    ];
    panels.forEach(function (p) {
      var g = root.group();
      drawScene(g, {
        theta1: p.th, ratio: state.ratio,
        cx: p.cx, cy: 268, left: p.cx - 150, right: p.cx + 150, bottom: 376, topY: 120,
        normUp: 136, normDown: 100, Lmax: 122, scale: 0.63,
        showNames: false, showThetaC: p.tc, subLeft: p.sl, subRight: p.sr
      });
      txt(root, p.cap, p.cx, 424, { size: 19, anchor: 'middle', baseline: 'middle', fill: INK });
      var sub = p.cap === '(a)' ? 'θ₁ < θc : refraction + reflection'
        : (p.cap === '(b)' ? 'θ₁ = θc : θ₂ = 90°, grazing exit'
          : 'θ₁ > θc : total internal reflection');
      txt(root, sub, p.cx, 452, { size: 12.5, anchor: 'middle', baseline: 'middle', fill: '#4a5a63' });
    });
    txt(root, 'Same physics, three regimes — set by how sin θ₁ compares with n₂ / n₁ = ' + state.ratio.toFixed(2)
      + '   (θc = ' + thc.toFixed(1) + '°)', 480, 508,
      { size: 13.5, anchor: 'middle', baseline: 'middle', fill: '#333' });
  }
  updateUiReadout();
}

function updateUiReadout() {
  var thc = Math.asin(Math.min(1, state.ratio)) / RAD;
  var s2 = Math.sin(state.theta1 * RAD) / state.ratio;
  var el = document.getElementById('uiReadout');
  if (!el) return;
  el.innerHTML = 'θc = <b>' + thc.toFixed(1) + '°</b> &nbsp; sin θ₂ = <b>' + s2.toFixed(3) + '</b><br>'
    + (s2 <= 1 ? '<span style="color:#12657f">refracted ray exists (θ₂ = '
      + (Math.asin(Math.min(1, s2)) / RAD).toFixed(1) + '°)</span>'
      : '<span style="color:#c0392b">no solution → total internal reflection</span>');
}

/* ---------- control handlers ---------- */
function update_incidentAngle(v) { state.theta1 = +v; render(); }
function update_indexRatio(v) { state.ratio = +v; render(); }
function toggle_viewMode(on) { state.triptych = !!on; render(); }

/* ---------- demo player ---------- */
var STEPS = [
  {
    title: '1. Ordinary refraction',
    narration: 'With θ₁ well below the critical angle, the ray splits: most light refracts into n₂, bending away from the normal because n₂ < n₁, while a weaker reflected ray returns into n₁ at the same angle θ₁.',
    state: { incidentAngle: 25, indexRatio: 0.67, triptych: false }
  },
  {
    title: '2. Approaching the critical angle',
    narration: 'Raise θ₁ and watch θ₂ grow much faster — the refracted ray swings toward the surface and dims as more energy goes into the reflected ray.',
    state: { incidentAngle: 38, indexRatio: 0.67, triptych: false }
  },
  {
    title: '3. θ₁ = θc : grazing exit',
    narration: 'At θ₁ ≈ 42° the refracted ray lies flat along the boundary, θ₂ = 90°. This is exactly the angle where sin(θc) = n₂/n₁.',
    state: { incidentAngle: 42, indexRatio: 0.67, triptych: false }
  },
  {
    title: '4. Total internal reflection',
    narration: 'Push past θc and the refracted ray disappears entirely — Snell\'s law has no solution. All the light stays trapped in n₁ as a single reflected ray.',
    state: { incidentAngle: 60, indexRatio: 0.67, triptych: false }
  },
  {
    title: '5. Change the media',
    narration: 'Hold θ₁ fixed and shrink n₂/n₁: the dashed θc reference swings inward, and the once-refracting ray suddenly becomes totally internally reflected — the critical angle belongs to the materials, not the ray.',
    state: { incidentAngle: 45, indexRatio: 0.5, triptych: false }
  },
  {
    title: '6. Compare with the textbook panels',
    narration: 'Switch to the triptych to see the three states side by side, exactly as the figure presents them: refraction, grazing at θc, and total internal reflection.',
    state: { incidentAngle: 60, indexRatio: 0.67, triptych: true }
  }
];
var curStep = 0;

function setControl(id, v) {
  var inp = document.getElementById(id + 'Input');
  if (inp) inp.value = v;
  var out = document.getElementById(id + 'Val');
  if (out) out.value = v;
}

function applyStep(i) {
  curStep = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  var st = STEPS[curStep].state;
  setControl('incidentAngle', st.incidentAngle);
  setControl('indexRatio', st.indexRatio.toFixed(2));
  state.theta1 = st.incidentAngle;
  state.ratio = st.indexRatio;
  state.triptych = !!st.triptych;
  var chk = document.getElementById('viewModeInput');
  if (chk) chk.checked = state.triptych;
  document.getElementById('stepTitle').textContent = STEPS[curStep].title;
  document.getElementById('demoNarration').textContent = STEPS[curStep].narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + STEPS.length;
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ---------- boot ---------- */
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: As the incident angle inside a denser medium increases, the refracted ray bends ever farther from the normal until, at the critical angle where sin(theta_c) = n2/n1, it grazes the surface and beyond which no light escapes — total internal reflection.
KEY INSIGHT (what students should walk away understanding): Total internal reflection is not a new law — it is Snell's law running out of room: once sin(θ₁) > n₂/n₁, there is no angle θ₂ whose sine equals n₁sin(θ₁)/n₂, so the refracted ray cannot exist and 100% of the light reflects.
DEMO STEPS: 6 guided steps — implement the step player in #ui

