      if (o.showNames) {
        var lp = { x: -Math.cos(th2), y: -Math.sin(th2) };
        var ax0 = cx + uf.x * Lu * 0.72, ay0 = cy + uf.y * Lu * 0.72;
        var nx = ax0 + lp.x * 58 * s, ny = Math.max(o.topY + 12 * ts, ay0 + lp.y * 58 * s);
        nameLabel(gl, 'Refracted ray', nx, ny, ax0, ay0, 11 * s, s, FR);
      }
    }
  }

  /* ── critical-angle reference ray ── */
  if (o.showThetaC) {
    var Lc = Math.min(o.Lmax * 0.95, below / Math.max(0.22, Math.cos(thc)));
    var uc = { x: -Math.sin(thc), y: Math.cos(thc) };
    gr.line(cx, cy, cx + uc.x * Lc, cy + uc.y * Lc)
      .stroke({ color: TEAL, width: 1.9 * s, linecap: 'round', opacity: 0.9 })
      .attr('stroke-dasharray', (10 * s) + ',' + (7 * s));
    hitLine(gh, cx, cy, cx + uc.x * Lc, cy + uc.y * Lc,
      'Critical-angle reference: θc = ' + (thc / RAD).toFixed(1) + '°',
      'The critical angle θc',
      'sin θc = n₂/n₁. This dashed ray marks the exact incidence at which the refracted ray would graze the surface. It depends only on the two media — not on the ray you send in.', 12 * s);
    arcBetween(gr, cx, cy, 100 * s, { x: 0, y: 1 }, uc, TEAL_D, 1.3 * s, true);
    var pc = wedgePos(cx, cy, -thc, 0, FT, 112 * s, 210 * s, below, true);
    thetaC(gl, pc.x, pc.y, FT);
  }

  /* ── incident ray ── */
  var ix = cx + ui.x * Lb, iy = cy + ui.y * Lb;
  gr.line(cx, cy, ix, iy).stroke({ color: TEAL, width: 2.5 * s, linecap: 'round' });
  arrowHead(gr, cx + ui.x * Lb * 0.5, cy + ui.y * Lb * 0.5, -ui.x, -ui.y, aw, TEAL);
  hitLine(gh, cx, cy, ix, iy, 'Incident ray — θ₁ = ' + o.theta1.toFixed(0) + '°', 'Incident ray',
    'The incoming ray travels inside n₁ and meets the boundary at θ₁ from the normal. Everything that happens next is decided by comparing sin θ₁ with n₂/n₁.', 14 * s);

  /* ── reflected ray ── */
  var rw = (2.0 + 2.0 * Rf) * s;
  var rx = cx + ur.x * Lb, ry = cy + ur.y * Lb;
  gr.line(cx, cy, rx, ry).stroke({ color: TEAL, width: rw, linecap: 'round' });
  arrowHead(gr, cx + ur.x * Lb * 0.64, cy + ur.y * Lb * 0.64, ur.x, ur.y, aw * (0.95 + 0.22 * Rf), TEAL);
  hitLine(gh, cx, cy, rx, ry,
    'Reflected ray — θ₁ = ' + o.theta1.toFixed(0) + '°, carrying ' + Math.round(Rf * 100) + '% of the light',
    'Reflected ray',
    'Reflection always obeys angle in = angle out. Its share of the energy grows as θ₁ approaches θc and reaches 100% beyond it — which is why this line thickens.', 14 * s);

  /* ── angle arcs + labels below the surface ── */
  arcBetween(gr, cx, cy, 46 * s, { x: 0, y: 1 }, ui, TEAL_D, 1.3 * s);
  arcBetween(gr, cx, cy, 46 * s, { x: 0, y: 1 }, ur, TEAL_D, 1.3 * s);
  var innerL = o.showThetaC ? thc : 0;
  var pL = wedgePos(cx, cy, -th1, -innerL, FT, 56 * s, o.showThetaC ? 130 * s : 210 * s, below, true);
  var pR = wedgePos(cx, cy, 0, th1, FT, 56 * s, 210 * s, below, true);
  function angLab(p, sub) {
    if (sub === 'c') thetaC(gl, p.x, p.y, FT);
    else txt(gl, 'θ₁', p.x, p.y, { size: FT, italic: true, family: 'Georgia, serif', anchor: 'middle', baseline: 'middle' });
  }
  angLab(pL, o.subLeft || '1');
  angLab(pR, o.subRight || '1');

  /* ── medium labels ── */
  txt(gl, 'n₂', o.left + 62 * s, cy - o.normUp * 0.55,
    { size: FN, italic: true, family: 'Georgia, serif', anchor: 'middle', baseline: 'middle' });
  txt(gl, 'n₁', o.right - 52 * s, cy + 46 * s,
    { size: FN, italic: true, family: 'Georgia, serif', anchor: 'middle', baseline: 'middle' });

  /* ── total internal reflection annotation ── */
  if (!hasRefr) {
    var tx0 = cx + 0.60 * (o.right - cx), ty0 = cy + 0.52 * (o.bottom - cy);
    var tt = txt(gl, 'Total internal\nreflection', tx0, ty0,
      { size: 21 * ts, anchor: 'middle', baseline: 'middle', haloW: 5 });
    inter(tt, 'No refracted ray exists — all the light stays inside n₁',
      'Total internal reflection',
      'For θ₁ > θc, sin θ₂ = sin θ₁ ÷ (n₂/n₁) would exceed 1. No real angle has a sine larger than 1, so Snell\'s law has no solution: the refracted ray simply does not exist and 100% of the light reflects.');
  }

  /* ── ray name labels ── */
  if (o.showNames) {
    var ai = { x: cx + ui.x * Lb * 0.80, y: cy + ui.y * Lb * 0.80 };
    var lpi = { x: -Math.cos(th1), y: Math.sin(th1) };
    var ilx = Math.max(o.left + 52 * ts, ai.x + lpi.x * 62 * s);
    var ily = Math.min(o.bottom - 20 * ts, ai.y + lpi.y * 62 * s - 18 * s);
    nameLabel(gl, 'Incident ray', ilx, ily, ai.x, ai.y, -12 * s, s, FR);

    var aq = { x: cx + ur.x * Lb * 0.80, y: cy + ur.y * Lb * 0.80 };
    var lpr = { x: Math.cos(th1), y: -Math.sin(th1) };
    var rlx = Math.min(o.right - 58 * ts, aq.x + lpr.x * 62 * s);
    var rly = Math.min(o.bottom - 20 * ts, Math.max(cy + 30 * s, aq.y + lpr.y * 62 * s));
    nameLabel(gl, 'Reflected ray', rlx, rly, aq.x, aq.y, 12 * s, s, FR);
  }

  return { thc: thc, th2: th2, hasRefr: hasRefr, graze: graze, R: Rf, T: Tf, sin2: sin2 };
}

/* ───────── readout card (single-panel view) ───────── */
function drawReadout(g, d) {
  var x = 654, y = 18, w = 288, h = 166;
  g.rect(w, h).move(x, y).radius(7).fill('#ffffff').stroke({ color: '#cfd8de', width: 1 }).opacity(0.95);
  var px = x + 14, py = y + 13, lh = 22;
  txt(g, 'θ₁ = ' + state.theta1.toFixed(0) + '°', px, py, { size: 16, fill: TEAL_D, weight: '700', halo: false });
  py += lh;
  if (d.hasRefr) {
    txt(g, 'θ₂ = ' + (d.th2 / RAD).toFixed(1) + '°' + (d.graze ? '  (grazing)' : ''), px, py,
      { size: 16, fill: TEAL_D, weight: '700', halo: false });
  } else {
    txt(g, 'θ₂ : none — no refracted ray', px, py, { size: 16, fill: '#c0392b', weight: '700', halo: false });
  }
  py += lh;
  txt(g, 'n₂/n₁ = ' + state.ratio.toFixed(2) + '     θc = ' + (d.thc / RAD).toFixed(1) + '°', px, py,
    { size: 15, fill: '#333', halo: false });
  py += 8;
  g.line(px, py + 10, x + w - 14, py + 10).stroke({ color: '#e2e7ea', width: 1 });
  py += 20;
  txt(g, 'n₁ sin θ₁ = n₂ sin θ₂', px, py, { size: 15, italic: true, family: 'Georgia, serif', halo: false });
  py += lh;
  txt(g, 'sin θ₂ = ' + d.sin2.toFixed(3) + (d.hasRefr ? '' : '  > 1  ✗'), px, py,
    { size: 15, italic: true, family: 'Georgia, serif', fill: d.hasRefr ? '#222' : '#c0392b', halo: false });
  py += lh;
  txt(g, 'sin θc = n₂/n₁ = ' + state.ratio.toFixed(2), px, py,
    { size: 15, italic: true, family: 'Georgia, serif', halo: false });

  inter(g.rect(w, h).move(x, y).fill('#fff').opacity(0),
    'Live values and the two governing equations',
    'Reading the numbers',
    'Snell\'s law is solved here for sin θ₂. While that number stays below 1 a refracted ray exists; the instant it passes 1 no angle can satisfy the equation, and refraction drops out of the physics entirely.');
}

/* ───────── views ───────── */
function drawSingle() {
  var thcDeg = Math.asin(Math.min(1, state.ratio)) / RAD;
  var d = drawScene(root, {
    theta1: state.theta1, ratio: state.ratio,
    cx: 400, cy: 300, left: 30, right: 930, bottom: 500, topY: 40,
    normUp: 260, normDown: 200, Lmax: 230, scale: 1, tscale: 1,
    showNames: true, showThetaC: state.theta1 > thcDeg + 3
  });
  drawReadout(root, d);
}

function drawTriptych() {
  var thcDeg = Math.asin(Math.min(1, state.ratio)) / RAD;
  var ta = Math.max(6, Math.min(state.theta1, thcDeg * 0.62));
  var tb = thcDeg;
  var tc = (state.theta1 > thcDeg + 2) ? Math.min(88, state.theta1) : Math.min(88, thcDeg + 18);
  var panels = [
    { cx: 165, th: ta, cap: '(a)', sl: '1', sr: '1', tc: false, names: true,
      tip: 'θ₁ < θc — the light splits into a refracted and a reflected ray',
      body: 'Below the critical angle Snell\'s law has a solution, so part of the light escapes into n₂ (bent away from the normal) and part reflects back into n₁.' },
    { cx: 490, th: tb, cap: '(b)', sl: 'c', sr: 'c', tc: false, names: false,
      tip: 'θ₁ = θc — the refracted ray grazes the surface, θ₂ = 90°',
      body: 'At exactly sin θ₁ = n₂/n₁ the refracted ray lies flat along the boundary. This is the definition of the critical angle θc.' },
    { cx: 815, th: tc, cap: '(c)', sl: '1', sr: '1', tc: true, names: false,
      tip: 'θ₁ > θc — total internal reflection',
      body: 'Past θc, sin θ₂ would have to exceed 1, which is impossible. The refracted ray vanishes and every bit of light is reflected back into the denser medium.' }
  ];
  panels.forEach(function (p) {
    var g = root.group();
    drawScene(g, {
      theta1: p.th, ratio: state.ratio,
      cx: p.cx, cy: 112, left: p.cx - 150, right: p.cx + 150, bottom: 252, topY: 18,
      normUp: 80, normDown: 140, Lmax: 148, scale: 0.62, tscale: 0.84,
      showNames: p.names, showThetaC: p.tc, subLeft: p.sl, subRight: p.sr
    });
    var cap = txt(root, p.cap, p.cx, 296, { size: 22, anchor: 'middle', baseline: 'middle' });
    inter(cap, p.tip, 'Panel ' + p.cap, p.body);
  });
}

/* ───────── render ───────── */
function render() {
  root.clear();
  if (state.triptych) { draw.viewbox(0, 0, 980, 330); drawTriptych(); }
  else { draw.viewbox(0, 0, 960, 560); drawSingle(); }
  updateUiReadout();
}

function updateUiReadout() {
  var thc = Math.asin(Math.min(1, state.ratio)) / RAD;
  var s2 = Math.sin(state.theta1 * RAD) / state.ratio;
  var el = document.getElementById('uiReadout');
  if (!el) return;
  el.innerHTML = 'θc = <b>' + thc.toFixed(1) + '°</b> &nbsp; sin θ₂ = <b>' + s2.toFixed(3) + '</b><br>'
    + (s2 <= 1 ? '<span style="color:#12657f">refracted ray exists (θ₂ = '
      + (Math.asin(Math.min(1, s2)) / RAD).toFixed(1) + '°)</span>'
      : '<span style="color:#c0392b">no solution → total internal reflection</span>');
}

/* ───────── controls ───────── */
function update_incidentAngle(v) { state.theta1 = +v; render(); }
function update_indexRatio(v) { state.ratio = +v; render(); }
function toggle_viewMode(on) { state.triptych = !!on; render(); }
function trigger_keyInsight() {
  showPopup('Key insight',
    'Total internal reflection is not a new law — it is Snell\'s law running out of room. Once sin θ₁ > n₂/n₁ there is no angle θ₂ whose sine equals n₁ sin θ₁ / n₂, so the refracted ray cannot exist and 100% of the light reflects back into the denser medium.');
}

/* ───────── guided demo ───────── */
var STEPS = [
  {
    title: '1. The textbook figure',
    narration: 'Three snapshots of one boundary. (a) θ₁ below the critical angle: the light splits into a refracted and a reflected ray. (b) θ₁ = θc: the refracted ray grazes the surface at θ₂ = 90°. (c) θ₁ > θc: nothing escapes. Hover any ray or panel for details.',
    state: { incidentAngle: 60, indexRatio: 0.67, triptych: true }
  },
  {
    title: '2. Ordinary refraction',
    narration: 'Switching to the single interactive panel: with θ₁ well below θc the ray splits. Most light refracts into n₂, bending away from the normal because n₂ < n₁, while a weaker reflected ray returns into n₁ at the same angle θ₁.',
    state: { incidentAngle: 25, indexRatio: 0.67, triptych: false }
  },
  {
    title: '3. Approaching the critical angle',
    narration: 'Raise θ₁ and watch θ₂ grow much faster — the refracted ray swings toward the surface and dims, while the reflected ray thickens as it takes a larger share of the energy.',
    state: { incidentAngle: 38, indexRatio: 0.67, triptych: false }
  },
  {
    title: '4. θ₁ = θc : grazing exit',
    narration: 'At θ₁ ≈ 42° the refracted ray lies flat along the boundary: θ₂ = 90°, marked by the right-angle square. This is exactly where sin θc = n₂/n₁.',
    state: { incidentAngle: 42, indexRatio: 0.67, triptych: false }
  },
  {
    title: '5. Total internal reflection',
    narration: 'Push past θc and the refracted ray disappears — sin θ₂ would have to exceed 1, so Snell\'s law has no solution. The dashed θc reference now appears, and all the light stays trapped in n₁.',
    state: { incidentAngle: 60, indexRatio: 0.67, triptych: false }
  },
  {
    title: '6. Change the media',
    narration: 'Hold θ₁ fixed and shrink n₂/n₁: θc collapses and a ray that used to refract is suddenly totally internally reflected. The critical angle belongs to the materials, not to the ray.',
    state: { incidentAngle: 45, indexRatio: 0.5, triptych: false }
  }
];
var curStep = 0;

function setControl(id, v) {
  var inp = document.getElementById(id + 'Input');
  if (inp) inp.value = v;
  var out = document.getElementById(id + 'Val');
  if (out) out.value = v;
}

function applyStep(i) {
  curStep = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  var st = STEPS[curStep].state;
  state.theta1 = st.incidentAngle;
  state.ratio = st.indexRatio;
  state.triptych = !!st.triptych;
  setControl('incidentAngle', st.incidentAngle);
  setControl('indexRatio', st.indexRatio.toFixed(2));
  var chk = document.getElementById('viewModeInput');
  if (chk) chk.checked = state.triptych;
  document.getElementById('stepTitle').textContent = STEPS[curStep].title;
  document.getElementById('demoNarration').textContent = STEPS[curStep].narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + STEPS.length;
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
